S=/private/tmp/claude-501/-HOME-chris-source-esoteric-absys/b126b1d8-c269-4983-bbfc-deaa2e7fcf81/scratchpad; cat > $S/tabl.pl <<'EOF'
# usage: REL='loop/1' perl -0 tabl.pl < in > out ; inserts tabling text
local $/; $_ = <STDIN>;
my $rel = $ENV{REL}; my $anchor = $ENV{ANCHOR};
s/% The same text in plain, coroutines, constraints and session; tabling.s\n% text differs only by its table directive \(programs\/swi-prolog\/README\.md\)\./% The tabling text: the plain text with the relations the problem defines\n% tabled, as in every tabling program here (programs\/swi-prolog\/README.md)./ or die "no share line";
s/(\n% END PROVENANCE\n)/\n%   tabling: the table\/1 directive on the problem's relations (SWI-Prolog\n%     manual, section "Tabled execution (SLG resolution)")$1/ or die "no prov";
s/(\n\Q$anchor\E)/\n:- table $rel.\n$1/ or die "no anchor";
print;
EOF
cd ~/cp-roles/implementation-1B-swi-prolog/programs/swi-prolog && for f in P04a P04b; do REL=loop/1 ANCHOR='% loop(x)' perl $S/tabl.pl < plain/$f.pl > tabling/$f.pl; done; for f in P04c P04d P04e P04f; do REL=alist/1 ANCHOR='% alist(s)' perl $S/tabl.pl < plain/$f.pl > tabling/$f.pl; done; diff plain/P04d.pl tabling/P04d.pl; for c in coroutines constraints session; do for f in P04a P04b P04c P04d P04e P04f; do cp plain/$f.pl $c/; done; done
